import React, { useState, useEffect } from 'react';
import './CSS/AdminDashboard.css';

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [selectedUser, setSelectedUser] = useState(null);
  const [detailModalItem, setDetailModalItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Simulated API Call with safe fallback
    const loadData = async () => {
      try {
        setUsers(defaultMockUsers);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const toggleStatus = (id) => {
    setUsers(users.map(u => 
      (u._id === id || u.id === id) 
        ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' } 
        : u
    ));
  };

  const toggleUserActivity = (user) => {
    const userId = user._id || user.id;
    const selectedId = selectedUser?._id || selectedUser?.id;
    if (selectedUser && selectedId === userId) {
      setSelectedUser(null);
    } else {
      setSelectedUser(user);
    }
  };

  const isRole = (userRole, targetRole) => {
    if (!userRole) return false;
    return userRole.toLowerCase() === targetRole.toLowerCase();
  };

  const filteredUsers = users.filter(user => {
    const term = (searchTerm || '').toLowerCase();
    const name = user.name || '';
    const email = user.email || '';
    const storeName = user.storeName || '';
    return name.toLowerCase().includes(term) || email.toLowerCase().includes(term) || storeName.toLowerCase().includes(term);
  });

  if (loading) {
    return <div style={{ padding: '40px', color: '#333' }}>Loading Admin Dashboard...</div>;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="tab-panel">
            <div className="kpi-grid">
              <div className="kpi-card">
                <div className="kpi-content">
                  <span className="kpi-title">Total Buyers</span>
                  <span className="kpi-number">{users.filter(u => isRole(u.role, 'user')).length}</span>
                </div>
              </div>
              <div className="kpi-card">
                <div className="kpi-content">
                  <span className="kpi-title">Verified Sellers</span>
                  <span className="kpi-number">{users.filter(u => isRole(u.role, 'seller')).length}</span>
                </div>
              </div>
            </div>

            <div className="dashboard-split-layout">
              <div className="split-main-card">
                <h3>Live Engagement Feed</h3>
                <table className="enhanced-table">
                  <thead>
                    <tr>
                      <th>User</th>
                      <th>Status</th>
                      <th>Activity</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.filter(u => isRole(u.role, 'user')).map(user => (
                      <tr key={user._id || user.id}>
                        <td>{user.name}</td>
                        <td>{user.status || 'Active'}</td>
                        <td>{user.activities?.[0]?.action || 'Logged in'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        );

      case 'user-info':
        return (
          <div className="tab-panel">
            <h3>User Directory</h3>
            <table className="enhanced-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {filteredUsers.filter(u => isRole(u.role, 'user')).map(user => (
                  <tr key={user._id || user.id}>
                    <td>{user.name}</td>
                    <td>{user.email}</td>
                    <td>{user.status || 'Active'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      default:
        return <div>Select a tab</div>;
    }
  };

  return (
    <div className="admin-wrapper" style={{ display: 'flex', minHeight: '100vh' }}>
      <aside className="admin-sidebar" style={{ width: '220px', padding: '20px' }}>
        <h2>Admin Panel</h2>
        <button onClick={() => setActiveTab('overview')}>Overview</button>
        <button onClick={() => setActiveTab('user-info')}>Users</button>
      </aside>
      <main className="admin-main" style={{ flex: 1, padding: '20px' }}>
        {renderContent()}
      </main>
    </div>
  );
};

const defaultMockUsers = [
  { id: '#101', name: 'Anisha', storeName: 'Apex Electronics', email: 'apexelectronics@seller.com', role: 'Seller', status: 'Active' },
  { id: '#102', name: 'Mona', email: 'mona@gmail.com', role: 'User', status: 'Active' }
];

export default AdminDashboard;
